   514  FRIBIDI_ENTRY FriBidiLevel
   515  fribidi_get_par_embedding_levels_ex (
   516    /* input */
   517    const FriBidiCharType *bidi_types,
   518    const FriBidiBracketType *bracket_types,
   519    const FriBidiStrIndex len,
   520    /* input and output */
   521    FriBidiParType *pbase_dir,
   522    /* output */
   523    FriBidiLevel *embedding_levels
   524  )
   525  {
   526    FriBidiLevel base_level, max_level = 0;
   527    FriBidiParType base_dir;
   528    FriBidiRun *main_run_list = NULL, *explicits_list = NULL, *pp;
   529    fribidi_boolean status = false;
   530    int max_iso_level = 0;
   531
   532    if UNLIKELY
   533      (!len)
   534      {
   535        status = true;
   536        goto out;
   537      }
   538
   539    DBG ("in fribidi_get_par_embedding_levels");
   540
   541    fribidi_assert (bidi_types);
   542    fribidi_assert (pbase_dir);
   543    fribidi_assert (embedding_levels);
   544
   545    /* Determinate character types */
   546    {
   547      /* Get run-length encoded character types */
   548      main_run_list = run_list_encode_bidi_types (bidi_types, bracket_types, len);
   549      if UNLIKELY
   550        (!main_run_list) goto out;
   551    }
   552
   553    /* Find base level */
   554    /* If no strong base_dir was found, resort to the weak direction
   555       that was passed on input. */
   556    base_level = FRIBIDI_DIR_TO_LEVEL (*pbase_dir);
   557    if (!FRIBIDI_IS_STRONG (*pbase_dir))
   558      /* P2. P3. Search for first strong character and use its direction as
   559         base direction */
   560      {
   561        int valid_isolate_count = 0;
   562        for_run_list (pp, main_run_list)
   563          {
   564            if (RL_TYPE(pp) == FRIBIDI_TYPE_PDI)
   565              {
   566                /* Ignore if there is no matching isolate */
   567                if (valid_isolate_count>0)
   568                  valid_isolate_count--;
   569              }
   570            else if (FRIBIDI_IS_ISOLATE(RL_TYPE(pp)))
   571              valid_isolate_count++;
   572            else if (valid_isolate_count==0 && FRIBIDI_IS_LETTER (RL_TYPE (pp)))
   573              {
   574                base_level = FRIBIDI_DIR_TO_LEVEL (RL_TYPE (pp));
   575                *pbase_dir = FRIBIDI_LEVEL_TO_DIR (base_level);
   576                break;
   577              }
   578          }
   579      }
   580    base_dir = FRIBIDI_LEVEL_TO_DIR (base_level);
   581    DBG2 ("  base level : %c", fribidi_char_from_level (base_level));
   582    DBG2 ("  base dir   : %s", fribidi_get_bidi_type_name (base_dir));
   583
   584  # if DEBUG
   585    if UNLIKELY
   586      (fribidi_debug_status ())
   587      {
   588        print_types_re (main_run_list);
   589      }
   590  # endif /* DEBUG */
   591
   592    /* Explicit Levels and Directions */
   593    DBG ("explicit levels and directions");
   594    {
   595      FriBidiLevel level, new_level = 0;
   596      int isolate_level = 0;
   597      FriBidiCharType override, new_override;
   598      FriBidiStrIndex i;
   599      int stack_size, over_pushed, first_interval;
   600      int valid_isolate_count = 0;
   601      int isolate_overflow = 0;
   602      int isolate = 0; /* The isolate status flag */
   603      struct
   604      {
   605        FriBidiCharType override; /* only LTR, RTL and ON are valid */
   606        FriBidiLevel level;
   607        int isolate;
   608        int isolate_level;
   609      } status_stack[FRIBIDI_BIDI_MAX_RESOLVED_LEVELS];
   610      FriBidiRun temp_link;
   611      FriBidiRun *run_per_isolate_level[FRIBIDI_BIDI_MAX_RESOLVED_LEVELS];
   612      int prev_isolate_level = 0; /* When running over the isolate levels, remember the previous level */
   613
   614      memset(run_per_isolate_level, 0, sizeof(run_per_isolate_level[0])
   615             * FRIBIDI_BIDI_MAX_RESOLVED_LEVELS);
   616
   617  /* explicits_list is a list like main_run_list, that holds the explicit
   618     codes that are removed from main_run_list, to reinsert them later by
   619     calling the shadow_run_list.
   620  */
   621      explicits_list = new_run_list ();
   622      if UNLIKELY
   623        (!explicits_list) goto out;
   624
   625      /* X1. Begin by setting the current embedding level to the paragraph
   626         embedding level. Set the directional override status to neutral,
   627         and directional isolate status to false.
   628
   629         Process each character iteratively, applying rules X2 through X8.
   630         Only embedding levels from 0 to 123 are valid in this phase. */
   631
   632      level = base_level;
   633      override = FRIBIDI_TYPE_ON;
   634      /* stack */
   635      stack_size = 0;
   636      over_pushed = 0;
   637      first_interval = 0;
   638      valid_isolate_count = 0;
   639      isolate_overflow = 0;
   640
   641      for_run_list (pp, main_run_list)
   642      {
   643        FriBidiCharType this_type = RL_TYPE (pp);
   644        RL_ISOLATE_LEVEL (pp) = isolate_level;
   645
   646        if (FRIBIDI_IS_EXPLICIT_OR_BN (this_type))
   647          {
   648            if (FRIBIDI_IS_STRONG (this_type))
   649              {                   /* LRE, RLE, LRO, RLO */
   650                /* 1. Explicit Embeddings */
   651                /*   X2. With each RLE, compute the least greater odd
   652                   embedding level. */
   653                /*   X3. With each LRE, compute the least greater even
   654                   embedding level. */
   655                /* 2. Explicit Overrides */
   656                /*   X4. With each RLO, compute the least greater odd
   657                   embedding level. */
   658                /*   X5. With each LRO, compute the least greater even
   659                   embedding level. */
   660                new_override = FRIBIDI_EXPLICIT_TO_OVERRIDE_DIR (this_type);
   661                for (i = RL_LEN (pp); i; i--)
   662                  {
   663                    new_level =
   664                      ((level + FRIBIDI_DIR_TO_LEVEL (this_type) + 2) & ~1) -
   665                      FRIBIDI_DIR_TO_LEVEL (this_type);
   666                    isolate = 0;
   667                    PUSH_STATUS;
   668                  }
   669              }
   670            else if (this_type == FRIBIDI_TYPE_PDF)
   671              {
   672                /* 3. Terminating Embeddings and overrides */
   673                /*   X7. With each PDF, determine the matching embedding or
   674                   override code. */
   675                for (i = RL_LEN (pp); i; i--)
   676                  {
   677                    if (stack_size && status_stack[stack_size-1].isolate != 0)
   678                      break;
   679                    POP_STATUS;
   680                  }
   681              }
   682
   683            /* X9. Remove all RLE, LRE, RLO, LRO, PDF, and BN codes. */
   684            /* Remove element and add it to explicits_list */
   685            RL_LEVEL (pp) = FRIBIDI_SENTINEL;
   686            temp_link.next = pp->next;
   687            move_node_before (pp, explicits_list);
   688            pp = &temp_link;
   689          }
   690        else if (this_type == FRIBIDI_TYPE_PDI)
   691          /* X6a. pop the direction of the stack */
   692          {
   693            for (i = RL_LEN (pp); i; i--)
   694              {
   695                if (isolate_overflow > 0)
   696                  {
   697                    isolate_overflow--;
   698                    RL_LEVEL (pp) = level;
   699                  }
   700
   701                else if (valid_isolate_count > 0)
   702                  {
   703                    /* Pop away all LRE,RLE,LRO, RLO levels
   704                       from the stack, as these are implicitly
   705                       terminated by the PDI */
   706                    while (stack_size && !status_stack[stack_size-1].isolate)
   707                      POP_STATUS;
   708                    over_pushed = 0; /* The PDI resets the overpushed! */
   709                    POP_STATUS;
   710                    isolate_level-- ;
   711                    valid_isolate_count--;
   712                    RL_LEVEL (pp) = level;
   713                    RL_ISOLATE_LEVEL (pp) = isolate_level;
   714                  }
   715                else
   716                  {
   717                    /* Ignore isolated PDI's by turning them into ON's */
   718                    RL_TYPE (pp) = FRIBIDI_TYPE_ON;
   719                    RL_LEVEL (pp) = level;
   720                  }
   721              }
   722          }
   723        else if (FRIBIDI_IS_ISOLATE(this_type))
   724          {
   725            /* TBD support RL_LEN > 1 */
   726            new_override = FRIBIDI_TYPE_ON;
   727            isolate = 1;
   728            if (this_type == FRIBIDI_TYPE_LRI)
   729              new_level = level + 2 - (level%2);
   730            else if (this_type == FRIBIDI_TYPE_RLI)
   731              new_level = level + 1 + (level%2);
   732            else if (this_type == FRIBIDI_TYPE_FSI)
   733              {
   734                /* Search for a local strong character until we
   735                   meet the corresponding PDI or the end of the
   736                   paragraph */
   737                FriBidiRun *fsi_pp;
   738                int isolate_count = 0;
   739                int fsi_base_level = 0;
   740                for_run_list (fsi_pp, pp)
   741                  {
   742                    if (RL_TYPE(fsi_pp) == FRIBIDI_TYPE_PDI)
   743                      {
   744                        isolate_count--;
   745                        if (valid_isolate_count < 0)
   746                          break;
   747                      }
   748                    else if (FRIBIDI_IS_ISOLATE(RL_TYPE(fsi_pp)))
   749                      isolate_count++;
   750                    else if (isolate_count==0 && FRIBIDI_IS_LETTER (RL_TYPE (fsi_pp)))
   751                      {
   752                        fsi_base_level = FRIBIDI_DIR_TO_LEVEL (RL_TYPE (fsi_pp));
   753                        break;
   754                      }
   755                  }
   756
   757                /* Same behavior like RLI and LRI above */
   758                if (FRIBIDI_LEVEL_IS_RTL (fsi_base_level))
   759                  new_level = level + 1 + (level%2);
   760                else
   761                  new_level = level + 2 - (level%2);
   762              }
   763
